-export const provenanceOf = (trailers: ReadonlyMap<string, string>): Provenance => {
-  const raw = trailers.get("Provenance");
-  if (raw === "authored" || raw === "inherited" || raw === "reconstructed") return raw;
+export const provenanceOf = (options: {
+  isGpgSigned: boolean;
+  gpgKeyMatches: boolean;
+}): Provenance => {
+  // Only trust "authored" if cryptographically verified via GPG signature
+  if (options.isGpgSigned && options.gpgKeyMatches) {
+    return "authored";
+  }
+  // All other cases: signature missing, invalid, or key unrecognized
   return "unknown";
 };
